(function(root){'use strict';
const VERSION='ac01-projects-1',SCHEMA='quidence_ac01_projects_v1',IDS=['food-trucks','shared-printer','missed-deadline'];
const key=id=>'quidence_ac01_'+id.replaceAll('-','_')+'_v1';
const clone=v=>JSON.parse(JSON.stringify(v));
function trucks(south){if(!Number.isFinite(south)||south<0)throw Error('Invalid demand');const d=[120,south];return [0,1].map(a=>[0,1].map(b=>[d[a]/(a===b?2:1)*5-100,d[b]/(a===b?2:1)*5-100]));}
function printer(f=0,cost=5,q=1){if(![f,cost,q].every(Number.isFinite)||f<0||cost<0||q<0||q>1)throw Error('Invalid rule');return[0,1].map(a=>[0,1].map(b=>{const benefit=a===0&&b===0?10:a===1&&b===1?3:6;return[benefit-(a===0?cost:f*q),benefit-(b===0?cost:f*q)];}));}
function model(id){const models={trucks80:()=>trucks(80),trucks50:()=>trucks(50),trucks60:()=>trucks(60),printer0:()=>printer(),printer15:()=>printer(1.5),printer3:()=>printer(3),printerTraining:()=>printer(0,2)};if(!models[id])throw Error('Unknown model');return models[id]();}
function analysis(p){const best=(player,other)=>{const values=[0,1].map(own=>player===0?p[own][other][0]:p[other][own][1]);return values[0]===values[1]?'both':values[0]>values[1]?'0':'1';};const r={A0:best(0,0),A1:best(0,1),B0:best(1,0),B1:best(1,1)};r.dominance=r.A0===r.A1&&r.A0===r.B0&&r.A0===r.B1&&r.A0!=='both'?r.A0:'none';r.ne=[];for(let a=0;a<2;a++)for(let b=0;b<2;b++)if(p[a][b][0]>=p[1-a][b][0]&&p[a][b][1]>=p[a][1-b][1])r.ne.push(''+a+b);return r;}
// A comma is a decimal separator, never a thousands separator. Reject mixed formats.
function number(raw){if(typeof raw!=='string'||!/^[-+]?\d+(?:[.,]\d+)?$/.test(raw.trim()))return null;const n=Number(raw.trim().replace(',','.'));return Number.isFinite(n)?n:null;}
function check(step,answers){if(!step.model)return[];const p=model(step.model),r=analysis(p),out=[];if(step.matrix)for(let a=0;a<2;a++)for(let b=0;b<2;b++)for(let player=0;player<2;player++){const id=`p${a}${b}${player}`;out.push({id,expected:p[a][b][player],status:number(answers[id])===null?'unanswered':number(answers[id])===p[a][b][player]?'matched':'recheck'});}for(const f of step.fields||[]){if(Object.hasOwn(r,f.id)){const answer=answers[f.id],expected=r[f.id];out.push({id:f.id,expected,status:!answer||(Array.isArray(answer)&&!answer.length)?'unanswered':JSON.stringify(Array.isArray(answer)?[...answer].sort():answer)===JSON.stringify(expected.length===0?['none']:expected)?'matched':'recheck'});}}return out;}
function fresh(id,sessionId){if(!IDS.includes(id))throw Error('Unknown activity');return{schema:SCHEMA,version:VERSION,activity:id,sessionId,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),step:0,records:{},events:[]};}
const object=v=>!!v&&typeof v==='object'&&!Array.isArray(v),date=v=>typeof v==='string'&&Number.isFinite(Date.parse(v));
const answers=v=>object(v)&&Object.entries(v).every(([k,x])=>k.length<100&&(typeof x==='string'||typeof x==='boolean'||Array.isArray(x)&&x.every(y=>typeof y==='string')));
function valid(v,id){return object(v)&&v.schema===SCHEMA&&v.version===VERSION&&v.activity===id&&typeof v.sessionId==='string'&&v.sessionId.length>0&&date(v.createdAt)&&date(v.updatedAt)&&Number.isInteger(v.step)&&v.step>=0&&v.step<20&&object(v.records)&&Object.values(v.records).every(r=>object(r)&&answers(r.draft)&&Array.isArray(r.submissions)&&r.submissions.every(s=>object(s)&&date(s.at)&&answers(s.answers)&&object(s.context)&&Array.isArray(s.context.fields)&&s.context.fields.every(f=>object(f)&&typeof f.id==='string'&&typeof f.label==='string')&&typeof s.context.prompt==='string'&&typeof s.context.story==='string'&&['en','es'].includes(s.locale)&&Array.isArray(s.support)&&s.support.every(e=>object(e)&&date(e.at)&&typeof e.type==='string')&&Array.isArray(s.checks)&&s.checks.every(c=>object(c)&&typeof c.id==='string'&&['matched','recheck','unanswered'].includes(c.status)))&&Array.isArray(r.support)&&r.support.every(s=>object(s)&&date(s.at)&&typeof s.type==='string'))&&Array.isArray(v.events)&&v.events.every(e=>object(e)&&date(e.at)&&typeof e.type==='string');}
function record(state,id){return state.records[id]||(state.records[id]={draft:{},submissions:[],support:[]});}
function open(storage,id,sessionId){const k=key(id);let raw=null,state,problem='';try{raw=storage.getItem(k);if(raw!==null){const v=JSON.parse(raw);if(!valid(v,id))throw Error('unreadable');state=v;}}catch{problem=raw!==null?'unreadable':'unavailable';}state=state||fresh(id,sessionId);return{key:k,state,original:raw,get problem(){return problem;},save(){if(problem)return{ok:false,reason:problem};try{if(storage.getItem(k)!==raw){problem='conflict';return{ok:false,reason:problem};}state.updatedAt=new Date().toISOString();const next=JSON.stringify(state);if(next.length>2*1024*1024){problem='full';return{ok:false,reason:problem};}storage.setItem(k,next);raw=next;return{ok:true};}catch{problem='unavailable';return{ok:false,reason:problem};}},changed(){try{return storage.getItem(k)!==raw;}catch{return true;}}};}
const api={VERSION,SCHEMA,IDS,key,clone,trucks,printer,model,analysis,number,check,fresh,valid,record,open};if(typeof module==='object'&&module.exports)module.exports=api;else root.QuidenceGameProjects=api;
})(typeof window==='undefined'?globalThis:window);
